    /// <summary>Creates the entry of a member.</summary>
    /// <param name="name">The name of the entry.</param>
    /// <param name="start">The start of the record.</param>
    /// <param name="member">The start of the member.</param>
    /// <param name="end">The end of the member.</param>
    /// <returns>The entry.</returns>
    private static (string Name, Entry Entry) Member(string name, byte* start, void* member, void* end)
    {
        return (name, new Entry((nuint)((byte*)end - (byte*)member), 0, (nuint)((byte*)member - start)));
    }

    /// <summary>Gets the alignment of a type: the offset at which a sequential structure places it after one byte.</summary>
    /// <typeparam name="T">The type.</typeparam>
    /// <returns>The alignment, in bytes.</returns>
    private static nuint AlignmentOf<T>()
        where T : unmanaged
    {
        return (nuint)(sizeof(AlignmentProbe<T>) - sizeof(T));
    }

    /// <summary>Describes an entry for a difference.</summary>
    /// <param name="entry">The entry.</param>
    /// <returns>The description.</returns>
    private static string Describe(Entry entry)
    {
        return global::System.FormattableString.Invariant($"size {entry.Size}, alignment {entry.Alignment}, offset {entry.Offset}");
    }

    /// <summary>The layout of a record or a member: its size, its alignment (0 for members and anonymous records), and its offset in its record.</summary>
    /// <param name="Size">The size, in bytes.</param>
    /// <param name="Alignment">The alignment, in bytes, or 0.</param>
    /// <param name="Offset">The offset, in bytes, or 0 for a record.</param>
    private readonly record struct Entry(nuint Size, nuint Alignment, nuint Offset);

    /// <summary>Maps <c>jade_layout_entry</c> of <c>build/layout/jade_layout.h</c>.</summary>
    [global::System.Runtime.InteropServices.StructLayout(global::System.Runtime.InteropServices.LayoutKind.Sequential)]
    private struct NativeEntry
    {
        /// <summary>The name of the entry, or null at the end of the table.</summary>
        public byte* Name;

        /// <summary>The size, in bytes.</summary>
        public nuint Size;

        /// <summary>The alignment of a named record, in bytes, or 0.</summary>
        public nuint Alignment;

        /// <summary>The offset of a member in its record, in bytes, or 0.</summary>
        public nuint Offset;
    }

    /// <summary>A structure that places a type after one byte, at its alignment.</summary>
    /// <typeparam name="T">The type.</typeparam>
    [global::System.Runtime.InteropServices.StructLayout(global::System.Runtime.InteropServices.LayoutKind.Sequential)]
    private struct AlignmentProbe<T>
        where T : unmanaged
    {
        /// <summary>The byte before the value.</summary>
        public byte Byte;

        /// <summary>The value, at the alignment of its type.</summary>
        public T Value;
    }
